    /// Register only collectors listed by the pinned Go package.
    pub fn register_metrics(&self, registry: &Registry) -> prometheus::Result<()> {
        registry.register(Box::new(self.cmd_duration.clone()))?;
        registry.register(Box::new(self.cmd_failed_duration.clone()))?;
        registry.register(Box::new(self.internal_cmd_duration.clone()))?;
        registry.register(Box::new(self.internal_cmd_failed_duration.clone()))?;
        registry.register(Box::new(self.request_duration.clone()))?;
        registry.register(Box::new(self.tso_best_batch_size.clone()))?;
        registry.register(Box::new(self.tso_batch_size.clone()))?;
        registry.register(Box::new(self.tso_retry_count.clone()))?;
        registry.register(Box::new(self.tso_batch_send_latency.clone()))?;
        registry.register(Box::new(self.request_forwarded.clone()))?;
        registry.register(Box::new(self.estimate_tso_latency_gauge.clone()))?;
        registry.register(Box::new(self.circuit_breaker_counters.clone()))?;
        registry.register(Box::new(self.query_region_best_batch_size.clone()))?;
        registry.register(Box::new(self.query_region_batch_size.clone()))?;
        registry.register(Box::new(self.query_region_batch_send_latency.clone()))?;
        Ok(())
    }
